What is the output of the following C code?
int main()
{
  int ary[] = {1, 3, 5};
  printf("%d %d", ary[-1], ary[4]);
  return 0;
}

Predict the output of the following C++ code.
#include <iostream>
using namespace std;
template <typename T>
T max(T &p, T &q)
{
  return (p > q ? p : q);
}
int main()
{
  int x = 55, y = 60, m;
  long a = 105, b = 53, n;
  m = max(x, y);
  n = max(a, b);
  cout << m << endl;
  cout << n << endl;
  return 0;
}

What will be the output of the following C code?
int main() {
  int a[] = {1, 2, 3, 4, 5}, *P;
  P = a;
  ++*P;
  printf(" %d ", *P);
  P += 2;
  printf(" %d ", *P);
}

